SELECT  FROM prd_requirement_acceptance
WHERE workspace_id = #{workspaceId} AND dispatch_id = #{dispatchId}
ORDER BY requirement_key ASC

SELECT  FROM prd_requirement_acceptance
WHERE workspace_id = #{workspaceId} AND dispatch_id = #{dispatchId}
  AND requirement_key = #{requirementKey}
